      '.lang-switch{position:fixed;right:16px;bottom:16px;z-index:9999;display:flex;gap:2px;padding:3px;' +
      'border-radius:999px;background:rgba(255,255,255,.85);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);' +
      'box-shadow:0 4px 18px rgba(180,90,70,.18),0 0 0 1px rgba(0,0,0,.06);font:600 13px/1 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}' +
      '.lang-switch button{display:flex;align-items:center;gap:5px;border:0;cursor:pointer;padding:7px 12px;border-radius:999px;' +
      'background:transparent;color:#6b5a55;transition:background .25s,color .25s,transform .15s}' +
      '.lang-switch button:hover{color:#e2705c}.lang-switch button:active{transform:scale(.95)}' +
      '.lang-switch button small{font-size:9px;opacity:.7;letter-spacing:.5px}' +
      '.lang-switch button.on{background:linear-gradient(135deg,#ee7c6a,#e2604d);color:#fff;box-shadow:0 2px 8px rgba(226,96,77,.4)}' +
      '@media (prefers-color-scheme:dark){.lang-switch{background:rgba(40,32,30,.8)}.lang-switch button{color:#d8c8c2}}';
